var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.Victron.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - victron_BAT.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// --->>> Batterieladung stoppen
schedule("*/10 * * * * *", async () => {
  // V3 - Cupra
  if ((getState('go-e.0.car').val == 2) && getState('go-e.0.allow_charging').val && getState('0_userdata.0.go-e.AUTO').val) {
    setState('javascript.0.Victron.ChargerV3' /* ChargerV3 */, true);
  } else {
    setState('javascript.0.Victron.ChargerV3' /* ChargerV3 */, false);
  }
  // V4 - Zoe
  if ((getState('0_userdata.0.go-e_V4.AUTO_V4').val && (getState('go-e.1.car').val > 1) && (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.ZIEL_V4').val) && (getState('go-e.1.allow_charging').val || getState('alias.0.Fronius.AC-Power').val > getState('0_userdata.0.go-e_V4.minPV_V4').val)) || getState('0_userdata.0.go-e_V4.NOT_V4').val) {
    setState('javascript.0.Victron.ChargerV4' /* ChargerV4 */, true);
  } else {
    setState('javascript.0.Victron.ChargerV4' /* ChargerV4 */, false);
  }
  // --- Charger aktiv ?
  if (getState('javascript.0.Victron.ChargerV3').val || getState('javascript.0.Victron.ChargerV4').val) {
    setState('mqtt.2.ioBroker.BAT_DisableBatteryCharge', 1);
    setState('mqtt.2.ioBroker.BAT_DisableFeedIn', 1);
  } else {
    setState('mqtt.2.ioBroker.BAT_DisableBatteryCharge', 0);
    setState('mqtt.2.ioBroker.BAT_DisableFeedIn', 0);
  }
});
// --- bei Lieferung ins Hausnetz, das Laden abschalten
// Einstellung geändert ?
on({ id: '0_userdata.0.Victron.MP-ESS_max_DC_Current' /* MP-ESS_max_DC_Current */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') < getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val) {
    setState('mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, (obj.state ? obj.state.val : ''));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-ESS/ Korrektur DC Current / MaxChargeCurrent auf: ',getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val,'A eingestellt'].join(''));
  }
  if ((obj.state ? obj.state.val : '') > getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val) {
    setState('mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-ESS/ Korrektur DC Current / MaxChargeCurrent auf: ',getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val,'A eingestellt'].join(''));
  }
});
on({ id: '0_userdata.0.Victron.MP-BAT_max_DC_Current' /* MP-BAT_max_DC_Current */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if ((obj.state ? obj.state.val : '') < getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val) {
    setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, (obj.state ? obj.state.val : ''));
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Korrektur DC Current / MaxChargeCurrent auf: ',getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val,'A eingestellt'].join(''));
  }
  if ((obj.state ? obj.state.val : '') > getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val) {
    setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Korrektur DC Current / MaxChargeCurrent auf: ',getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val,'A eingestellt'].join(''));
  }
});
// Wertbegrenzung
on({ id: 'mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val > getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val) {
    setState('mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val);
  }
});
on({ id: 'mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val > getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val) {
    setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val);
  }
});
// LOG
on({ id: 'mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, change: 'ne', ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-ESS/ max Charge Current wurde geändert auf: ',getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val,'A'].join(''));
});
on({ id: 'mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, change: 'ne', ack: true }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ max Charge Current wurde geändert auf: ',getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val,'A'].join(''));
});

// BEGRENZUNGEN - maximaler Ladestrom
// BAT-DC max Charge Current begrenzen
// MP-BAT
// Gobel - max Charge Current begrenzen
// Gobel - Ladeleistung begrenzen
on({ id: 'alias.0.Gobel.Power' /* N/c0619ab336ed/battery/512/Dc/0/Power */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  // auf x kW die Ladeleistung einregeln
  if (getState('alias.0.Gobel.Power').val > getState('0_userdata.0.Victron.maxPowerChargeGobel').val) {
    if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val > Math.abs(getState('alias.0.MP-BAT.DC-Current').val) + 5) {
      setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val - 10));
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'MP-BAT/ Begrenzung Gobel Leistung / MaxChargeCurrent: ' + String(getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val - 10));
    }
  }
  // ab x+1 kW die Ladung unterbrechen
  if (getState('alias.0.Gobel.Power').val > getState('0_userdata.0.Victron.maxPowerChargeGobel').val + 1000) {
    setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, 0);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'MP-BAT/ Korrektur Gobel Leistung / MaxChargeCurrent auf 0 gestellt');
  }
});

// --- REGELUNG DC Current
schedule("*/10 * * * * *", async () => {
  // ESS
  if ((getState('alias.0.Gobel.Soc SmartShunt').val >= getState('0_userdata.0.Victron.Max_SOC_Setpoint').val) && (!getState('0_userdata.0.Victron.TOP-Balancing').val)) {
    setState('mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, 1);
  } else if (getState('mqtt.1.ioBroker.ESS_MaxChargeCurrent').val != getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val) {
    setState('mqtt.1.ioBroker.ESS_MaxChargeCurrent' /* ioBroker/ESS_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-ESS_max_DC_Current').val);
  }
  // BAT
  if (getState('alias.0.Gobel.Soc SmartShunt').val >= getState('0_userdata.0.Victron.Max_SOC_Setpoint').val) {
    // Max SOC
    setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, 1);
  } else if (getState('0_userdata.0.Victron.TOP-Balancing').val) {
    if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val != 10) {
      setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, 10);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'MP-BAT/ TOP-Balancing aktiv, MaxChargeCurrent auf 10A eingestellt');
    }
  } else if ((!getState('javascript.0.Victron.ChargerV3').val) && (!getState('javascript.0.Victron.ChargerV4').val)) {
    // Visu - Setting
    if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val != getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val) {
      setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'MP-BAT/ MaxCharge unterschliedlich zu Max DC: ' + String(getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val));
    }
    // Unterstützung reduzieren auf das Notwendige
    // wenn Charger dicharged ins Netz
    // oder wenn New-Grid ins Netz liefert
    if (getState('alias.0.EM24 New Grid.Power').val < -500 && getState('alias.0.MP-ESS.DC-Current').val < 0) {
      setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, (Math.min(Math.max(getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val - 10, 0), 210)));
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Minus / MaxChargeCurrent auf: ',getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val,'A eingestellt'].join(''));
      if (getState('alias.0.MP-BAT.DC-Current').val > getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val + 20) {
        setState('mqtt.2.ioBroker.BAT_DisableBatteryCharge', 1);
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), 'MP-BAT / ---> Disable Charge wurde aktiviert !');
      }
    } else {
      // wenn mehr Strom in die Batterie kann
      if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val < getState('0_userdata.0.Victron.MP-BAT_max_DC_Current').val && (getState('alias.0.EM24 New Grid.Power').val > -2000 || getState('alias.0.Gobel.Current').val > 0)) {
        setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, (Math.min(Math.max(getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val + 10, 0), 210)));
        if (getState('mqtt.2.ioBroker.BAT_DisableBatteryCharge').val) {
          setState('mqtt.2.ioBroker.BAT_DisableBatteryCharge', 0);
        }
        await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Plus / MaxChargeCurrent auf: ',getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val,'A eingestellt'].join(''));
      }
    }
  } else {
    if (getState('mqtt.2.ioBroker.BAT_MaxChargeCurrent').val != 1) {
      setState('mqtt.2.ioBroker.BAT_MaxChargeCurrent' /* ioBroker/BAT_MaxChargeCurrent */, 1);
    }
  }
});

// max WR Leistung berechnen
schedule("*/10 * * * * *", async () => {
  if (getState('0_userdata.0.Victron.TOP-Balancing').val) {
    // TOP Balancing
    if (getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val != 1) {
      setState('mqtt.2.ioBroker.BAT_maxWRLeistung', 1);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max WR Leistung auf: ',getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val,'W eingestellt, TOP Balancing'].join(''));
    }
  } else if ((getState('alias.0.EM24 Hall Grid.HallGrid_Power_Plus').val > 100) && (getState('alias.0.EM24 New Grid.Power_Plus').val <= 0) && (getState('alias.0.Gobel.Soc SmartShunt').val > getState('0_userdata.0.Victron.Old_Grid_Setpoint_minSOC').val) && getState('0_userdata.0.Victron.HallGrid_Support').val) {
    // - Halle bezieht vom Netz
    setState('mqtt.2.ioBroker.BAT_maxWRLeistung', 11000);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max WR Leistung auf: ',getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val,'W eingestellt, Überschussleistung von Haus zu Halle.'].join(''));
  } else if (getState('alias.0.Gobel.Soc SmartShunt').val <= getState('0_userdata.0.Victron.Old_Grid_Setpoint_minSOC').val) {
    // SOC >  X %
    if (getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val != 1500) {
      setState('mqtt.2.ioBroker.BAT_maxWRLeistung', 1500);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max WR Leistung auf: ',getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val,'W eingestellt, SOC > 50%'].join(''));
    }
  } else if ((getState('0_userdata.0.go-e_V4.MinLadung_V4').val && (getState('renault.0.VF1AG000966808321.battery-status.batteryLevel').val < getState('0_userdata.0.go-e_V4.MinLadungProzent_V4').val)) || getState('0_userdata.0.go-e_V4.NOT_V4').val) {
    // bei Not- od. Min-Ladung begrenzen
    if (getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val != 100) {
      setState('mqtt.2.ioBroker.BAT_maxWRLeistung', 100);
      await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max WR Leistung auf: ',getState('mqtt.2.ioBroker.BAT_maxWRLeistung').val,'W eingestellt, Not- oder Minladung'].join(''));
    }
  } else {
    // DEFAULT
  }
});

// max AC Input Current
schedule("*/10 * * * * *", async () => {
  if ((getState('alias.0.EM24 Hall Grid.Power').val > 100) && (getState('alias.0.Gobel_Master.SOC').val < 30) && (getState('mqtt.2.ioBroker.BAT_MaxACInputCurrent').val > 0)) {
    setState('mqtt.2.ioBroker.BAT_MaxACInputCurrent' /* ioBroker/BAT_MaxACInputCurrent */, 0);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max AC Input Current auf: ',getState('mqtt.2.ioBroker.BAT_MaxACInputCurrent').val,'A eingestellt'].join(''));
  } else if ((getState('alias.0.EM24 Hall Grid.Power').val < 0) && (getState('alias.0.Fronius.AC-Power').val > 500) && (getState('mqtt.2.ioBroker.BAT_MaxACInputCurrent').val == 0)) {
    setState('mqtt.2.ioBroker.BAT_MaxACInputCurrent' /* ioBroker/BAT_MaxACInputCurrent */, 50);
    await Logfile(formatDate(new Date(), 'YYYY.MM.DD'), ['MP-BAT/ Max AC Input Current auf: ',getState('mqtt.2.ioBroker.BAT_MaxACInputCurrent').val,'A eingestellt'].join(''));
  }
});

// CCL Berechnung
schedule("* * * * * *", async () => {
});


